from collections import defaultdict

def build_adj_list(edges):
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)  # undirected
    return adj

def dfs(adjList):
    visited = set()
    def helper(node):
        if node in visited:
            return
        visited.add(node)
        for nei in adjList[node]:
            helper(nei)
    for node in adjList:
        if node not in visited:
            helper(node)
